// 5-touch cadence. The lead's status = the touch that is due now.
// minDays = business days that must pass since the last activity.
// Status values must match your Zoho "Lead Status" picklist exactly (add them there first).
const STAGES = {
  'Touch 1 · Email':    { step: 1, channel: 'Email',    next: 'Touch 2 · Telegram', minDays: 0 },
  'Touch 2 · Telegram': { step: 2, channel: 'Telegram', next: 'Touch 3 · Email',    minDays: 2 },
  'Touch 3 · Email':    { step: 3, channel: 'Email',    next: 'Touch 4 · WhatsApp', minDays: 3 },
  'Touch 4 · WhatsApp': { step: 4, channel: 'WhatsApp', next: 'Touch 5 · Final',    minDays: 3 },
  'Touch 5 · Final':    { step: 5, channel: 'Email',    next: 'Paused',                minDays: 3 },
};
const CFG = $('Config').first().json;
const ZOHO_UI = CFG.zoho_ui_domain;
const MAX = Number(CFG.max_leads_per_run) || 30;

function businessDaysSince(iso) {
  if (!iso) return 999;
  const start = new Date(iso);
  if (isNaN(start)) return 999;
  let days = 0;
  const d = new Date(start); d.setHours(0, 0, 0, 0);
  const end = new Date(); end.setHours(0, 0, 0, 0);
  while (d < end) {
    d.setDate(d.getDate() + 1);
    const wd = d.getDay();
    if (wd !== 0 && wd !== 6) days++;
  }
  return days;
}

const res = $input.first()?.json || {};
// Zoho returns an empty body when nothing matches; an error object means auth/API trouble, so stop instead of silently doing nothing.
if (res.status === 'error' || res.code === 'INVALID_TOKEN' || res.code === 'AUTHENTICATION_FAILURE' || res.code === 'INVALID_QUERY') {
  throw new Error('Zoho search failed: ' + (res.code || '') + ' ' + (res.message || ''));
}
const leads = res.data || [];
const seen = new Set();
const out = [];
for (const l of leads) {
  const status = String(l.Lead_Status || '').trim();
  const st = STAGES[status];
  if (!st || seen.has(l.id)) continue;
  seen.add(l.id);
  const last = l.Last_Activity_Time || l.Modified_Time || l.Created_Time;
  const waited = businessDaysSince(last);
  if (waited < st.minDays) continue;
  // score_AI and bant_qulif are custom fields filled by the lead-qualification workflow; empty score = Warm
  const score = (l.score_AI === null || l.score_AI === undefined || l.score_AI === '') ? NaN : Number(l.score_AI);
  const temp = Number.isFinite(score) ? (score >= 71 ? 'Hot' : score >= 31 ? 'Warm' : 'Cold') : 'Warm';
  out.push({ json: {
    lead_id: l.id,
    name: l.Full_Name || [l.First_Name, l.Last_Name].filter(Boolean).join(' '),
    first_name: l.First_Name || '',
    company: l.Company || '',
    description: l.Description || '',
    bant: l.bant_qulif ?? '',
    score: Number.isFinite(score) ? score : null,
    temperature: temp,
    status,
    step: st.step,
    channel: st.channel,
    next_status: st.next,
    business_days_waited: waited === 999 ? null : waited,
    crm_link: ZOHO_UI + '/crm/tab/Leads/' + l.id,
  } });
}
// Cap the batch so one run never floods the manager.
return out.slice(0, MAX);

